const msg = $('When Telegram Message Received').first().json.message;

return [{
  json: {
    chatId: msg.chat.id,
    userRequest: msg.text
  }
}];

const raw = $input.first().json.output ?? $input.first().json;

let result;

try {
  result = typeof raw === "string" ? JSON.parse(raw) : raw;
} catch (e) {
  throw new Error("AI response was not valid JSON: " + e.message);
}

const requiredTopLevel = ["operation", "rule", "ambiguous"];

for (const field of requiredTopLevel) {
  if (!(field in result)) {
    throw new Error(`AI output missing required field: ${field}`);
  }
}

const fieldLabels = {
  enabled: "Enabled",
  sequence: "Sequence",
  categories: "Categories",
  nosync: "No Sync",
  description: "Description",

  interface: "Interface",

  action: "Action",
  direction: "Direction",
  protocol: "Protocol",
  ipprotocol: "IP Version",

  source_net: "Source",
  source_port: "Source Port",

  destination_net: "Destination",
  destination_port: "Destination Port",

  // NAT fields
  source: "Source",
  destination: "Destination",
  target: "Internal Target",
  "local-port": "Internal Port",

  log: "Logging",
  gateway: "Gateway",
};

function requiredFieldsFor(operation, rule) {
  // Existing firewall rule logic
  if (operation === "filter_rule_create") {
    const fields = ["action", "source_net", "destination_net"];

    if (rule.source_port || rule.destination_port) {
      fields.push("protocol");
    }

    return fields;
  }

  // New NAT rule validation
  if (operation === "destination_nat_create") {
    return ["interface", "protocol", "target"];
  }

  return [];
}

const rule = result.rule || {};

const required = requiredFieldsFor(result.operation, rule);

const missing = required.filter(
  (f) =>
    !(f in rule) || rule[f] === "" || rule[f] === null || rule[f] === undefined,
);

const ipv4Pattern = /^(\d{1,3}\.){3}\d{1,3}(\/\d{1,2})?$/;

const ipv6Pattern = /^[0-9a-fA-F:]+(\/\d{1,3})?$/;

const aliasOrAnyPattern = /^(any|[A-Za-z][A-Za-z0-9_]*)$/;

function isValidNet(value) {
  if (!value) return true;

  if (ipv4Pattern.test(value)) return true;

  if (value.includes(":") && ipv6Pattern.test(value)) return true;

  if (aliasOrAnyPattern.test(value)) return true;

  return false;
}

const invalid = [];

// Existing firewall validation
for (const field of ["source_net", "destination_net"]) {
  if (rule[field] && !isValidNet(rule[field])) {
    invalid.push(field);
  }
}

// NAT nested validation

if (rule.source && rule.source.network && !isValidNet(rule.source.network)) {
  invalid.push("source.network");
}

if (
  rule.destination &&
  rule.destination.network &&
  !isValidNet(rule.destination.network)
) {
  invalid.push("destination.network");
}

// Normalize interface value only for validation compatibility
// Do not modify output
if (rule.interface && typeof rule.interface === "string") {
  const allowedLike = /^[a-zA-Z0-9_]+$/;

  if (!allowedLike.test(rule.interface)) {
    invalid.push("interface");
  }
}

if (result.operation === "unknown") {
  return [
    {
      json: {
        valid: false,
        result:
          "The request could not be resolved to a single firewall operation. Please describe only one request at a time.",
        missing,
        invalid,
      },
    },
  ];
}

if (missing.length > 0) {
  const labels = missing.map((f) => fieldLabels[f] || f).join(", ");

  return [
    {
      json: {
        valid: false,
        result: `The following information is missing: ${labels}`,
        missing,
        invalid,
      },
    },
  ];
}

if (invalid.length > 0) {
  const labels = invalid.map((f) => fieldLabels[f] || f).join(", ");

  return [
    {
      json: {
        valid: false,
        result: `The following fields have an invalid value: ${labels}`,
        missing,
        invalid,
      },
    },
  ];
}

if (result.ambiguous === true) {
  return [
    {
      json: {
        valid: false,
        result:
          "The request is ambiguous and needs clarification before it can be confirmed.",
        missing,
        invalid,
      },
    },
  ];
}

return [
  {
    json: {
      valid: true,
      ...result,
      missing,
      invalid,
    },
  },
];

const cq = $('When Telegram Message Received').first().json.callback_query
return [{
  json: {
    chatId: cq.message.chat.id,
    messageId: cq.message.message_id,
    decision: cq.data,
    callbackQueryId: cq.id
  }
}];

// Maps the parser's operation to a real OPNsense endpoint, method and request body.
// The LLM is intentionally never allowed to invent the URL or payload itself.
const a = $input.first().json;
const rule = { ...(a.rule || {}) };

const endpointMap = {
  filter_rule_create: { api: "firewall/filter/add_rule", method: "POST" },

  destination_nat_create: {
    api: "firewall/d_nat/add_rule",
    method: "POST",
  },
};

const applyEndpointMap = {
  filter_rule_create: { api: "firewall/filter/apply", method: "POST" },

  destination_nat_create: {
    api: "firewall/d_nat/apply",
    method: "POST",
  },
};

const endpoint = endpointMap[a.operation];
if (!endpoint) {
  throw new Error(
    `No OPNsense endpoint mapping is defined for operation: ${a.operation}`,
  );
}
const applyEndpoint = applyEndpointMap[a.operation];
if (!applyEndpoint) {
  throw new Error(
    `No OPNsense apply endpoint mapping is defined for operation: ${a.operation}`,
  );
}

return [
  {
    json: {
      chatId: a.chatId,
      opnsenseMethod: endpoint.method,
      opnsenseUrl: endpoint.api,
      opnsenseApplyMethod: applyEndpoint.method,
      opnsenseApplyUrl: applyEndpoint.api,
      opnsenseBody: { rule },
    },
  },
];

const input = $input.first().json;

const raw = input.output ?? input;

let result;

try {
  result = typeof raw === "string" ? JSON.parse(raw) : raw;
} catch (e) {
  throw new Error("Invalid AI JSON: " + e.message);
}

const rule = result.rule || {};

// Only normalize NAT rules
if (result.operation === "destination_nat_create") {
  // interface
  if (rule.interface) {
    rule.interface = rule.interface.toLowerCase();
  }

  // protocol
  if (rule.protocol) {
    rule.protocol = rule.protocol.toLowerCase();
  }

  // source conversion
  if (!rule.source) {
    rule.source = {
      not: "0",
      network: rule.source_network || "",
      port: rule.source_port || "",
    };
  }

  // destination conversion
  if (!rule.destination) {
    rule.destination = {
      not: "0",
      network: rule.destination_network || "",
      port: rule.destination_port || "",
    };
  }

  // local port
  if (rule.local_port && !rule["local-port"]) {
    rule["local-port"] = rule.local_port;
  }

  // remove old fields
  delete rule.source_network;
  delete rule.source_port;

  delete rule.destination_network;
  delete rule.destination_port;

  delete rule.local_port;

  // default OPNsense fields

  rule.disabled ??= "0";
  rule.sequence ??= "600";
  rule.category ??= "";
  rule.descr ??= "";

  rule.ipprotocol ??= "";

  rule.source ??= {
    not: "0",
    network: "",
    port: "",
  };

  rule.destination ??= {
    not: "0",
    network: "",
    port: "",
  };

  rule.poolopts ??= "";
  rule.nordr ??= "0";
  rule.log ??= "0";
  rule.nosync ??= "0";
  rule.natreflection ??= "";
  rule.tag ??= "";
  rule.tagged ??= "";
  rule.pass ??= "rule";
}

return [
  {
    json: {
      ...result,
      rule,
    },
  },
];

const chatId = $('Parse Callback').first().json.chatId
const decision = $("When Telegram Message Received").first().json.callback_query.data;
const pending = $input.first().json;

if (Object.keys(pending).length === 0) {
  return [{ json: { found: false, chatId, decision } }];
}

if ($input.all().length > 0) {
  return [
    {
      json: {
        found: true,
        chatId: $input.first().json.chat_id,
        decision,
        operation: pending.operation,
        rule: JSON.parse(pending.rule),
      },
    },
  ];
} else {
  return [{ json: { found: false, chatId, decision } }];
}

const raw = $('Add IDs Form').first().json['Telegram Numeric IDs'] || '';

const ids = raw
  .split(/[\n,]+/)
  .map(v => v.trim())
  .filter(v => v.length > 0)
  .filter(v => /^\d+$/.test(v))
  .map(v => Number(v));

const uniqueIds = [...new Set(ids)];

return uniqueIds.map(id => ({ json: { telegram_id: id } }));

