const interfaces = $input.first().json.body.rows
  .filter(i => i.enabled && i.identifier && i.identifier !== "lo0")
  .map(i => ({
    identifier: i.identifier,
    description: i.description,
    is_physical: i.is_physical,
    groups: i.groups || [],
    addr4: i.addr4 || null,
    addr6: i.addr6 || null,
    ipv6: (i.ipv6 || []).map(x => x.ipaddr),
    gateways: i.gateways || []
  }));

return [{ json: { interfaces } }];

const a = $('Validate AI Output').first().json;
const audit = $input.first().json.output;
const rule = a.rule || {};
const chatId = $('Normalize Input').first().json.chatId;

const opLabels = {
  filter_rule_create: "Create Firewall Rule",
  destination_nat_create: "Create NAT Rule",
};

const fieldLabels = {
  enabled: "Enabled",
  sequence: "Sequence",
  categories: "Categories",
  nosync: "No Sync",
  description: "Description",

  interface: "Interface",

  action: "Action",
  direction: "Direction",
  ipprotocol: "IP Version",
  protocol: "Protocol",

  source_net: "Source",
  source_port: "Source Port",

  destination_net: "Destination",
  destination_port: "Destination Port",

  // NAT
  source: "Source",
  destination: "Destination",
  target: "Internal Target",
  "local-port": "Internal Port",

  log: "Logging",
  gateway: "Gateway",
};

function prettifyKey(key) {
  if (fieldLabels[key]) {
    return fieldLabels[key];
  }

  return key.replace(/_/g, " ").replace(/\b\w/g, (c) => c.toUpperCase());
}

// Recursive flatten for nested NAT objects
function flattenObject(obj, prefix = "") {
  let rows = [];

  for (const [key, value] of Object.entries(obj)) {
    const fullKey = prefix ? `${prefix}.${key}` : key;

    if (value !== null && typeof value === "object" && !Array.isArray(value)) {
      rows.push(...flattenObject(value, fullKey));
    } else {
      rows.push([fullKey, value]);
    }
  }

  return rows;
}

const rows = [["Operation", opLabels[a.operation] || a.operation]];

for (const [key, value] of flattenObject(rule)) {
  if (value === undefined || value === null || value === "") {
    continue;
  }

  rows.push([prettifyKey(key), value]);
}


const ruleSection = rows.map(([k, v]) => `<b>${k}:</b> ${v}`).join("\n");

const severityIcons = {
  none: "✅",
  low: "🟡",
  medium: "🟠",
  high: "🔴",
  critical: "🚨",
};

const statusLine =
  audit.status === "ok"
    ? "✅ <b>No issues detected</b>"
    : `${severityIcons[audit.severity] || "⚠️"} <b>Problem detected (${audit.severity})</b>`;

let auditSection = `${statusLine}\n<b>Reason:</b> ${audit.reason}`;

if (audit.overlap_detected) {
  auditSection += `\n<b>Overlap detected:</b> yes`;
}

if (audit.problem_source && audit.problem_source !== "none") {
  const sourceLabel =
    audit.problem_source === "new_rule" ? "New rule" : "Existing rule(s)";
  auditSection += `\n<b>Problem source:</b> ${sourceLabel}`;
}

if (audit.existing_rule_issues && audit.existing_rule_issues.length > 0) {
  auditSection +=
    "\n\n<b>Affected existing rules:</b>\n" +
    audit.existing_rule_issues
      .map((i) => `• <code>${i.uuid}</code> — ${i.issue}`)
      .join("\n");
}

const telegramText =
  "The following action will be performed:\n\n" +
  ruleSection +
  "\n\n———\n\n" +
  auditSection +
  "\n\nProceed?";

return [
  {
    json: {
      chatId,
      operation: a.operation,
      rule: a.rule,
      audit,
      telegramText,
    },
  },
];
